architecture.h4_f:
msg = CBOR{v:1, text, reply_to, send_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, reply_to?, thread_id?, mentions?, send_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
ខ្សែ = CBOR{
  v: 1,
  ciphertext: hex(ct), // ប្រវែងអថេរ
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  send_at៖ unix_ms
}

cryptoWire.h5_f:
ខាងក្រៅ = CBOR{
  ប្រភព_node៖ hex32,
  target_user៖ int64,
  inner_ciphertext: បៃ,
  inner_nonce៖ បៃ,
  send_at៖ unix_ms
}
sig = Ed25519-Sign(source_priv, ខាងក្រៅ)
POST /federation/deliver { envelope: outer, sig: hex64 }

auth.h1_f:
POST /api/authentication/ចុះឈ្មោះ
  { ឈ្មោះអ្នកប្រើ, ពាក្យសម្ងាត់, x25519_public_key, display_name, ទូរស័ព្ទ?, អ៊ីមែល?, avatar_emoji }

ការឆ្លើយតប 201 បានបង្កើត៖
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token payload:
  { sub: user_id, jti: device_id, វាយ: "access", exp: now + 15min }
refresh_token payload:
  { sub: user_id, jti: device_id, វាយ: "refresh", exp: now + 30d }

HS256-ចុះហត្ថលេខាដោយសម្ងាត់ 64-byte របស់ node ពី .env

auth.h4_f:
register_begin(): challenge = rand(32)
                    ជម្រើស = { rp.id, user.id, pubKeyCredParams, challenge }
                    ជម្រើសត្រឡប់មកវិញ

register_finish(បញ្ជាក់)៖
  ផ្ទៀងផ្ទាត់ការបញ្ជាក់ប្រឆាំងនឹងTPM / Secure Enclave root CA
  រក្សាទុក { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/ផ្ទៀងផ្ទាត់ { nonce }
  →ឧបករណ៍ថ្មីដែលបានចុះឈ្មោះ; JWTs បានត្រឡប់មកវិញ។

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-អ៊ិនគ្រីប(room_key, nonce, CBOR_payload, aad=room_id)

Fan-out frame៖ { type:"m", room, msg:{id, ct, nonce, sender_pseudo, send_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {upload_id, chunk_size}
កំណាត់ PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← ២០៤
បញ្ចប់ POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL នៅមិនទាន់បញ្ចប់៖ 24 ម៉ោង។

files.h4_f:
deny_list = {
  "កម្មវិធី/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
ប្រសិនបើ magic.from_buffer(buf[:1024]) ក្នុង deny_list៖ ត្រឡប់ 415

presence.h1_f:
ម៉ាស៊ីនភ្ញៀវ៖ នៅលើការចុចគ្រាប់ចុចដំបូង → ផ្ញើ {type:"t", state:"start"}
         មិនមានការផ្ញើទៀតទេសម្រាប់ 3 វិនាទីលុះត្រាតែមានការផ្លាស់ប្តូរស្ថានភាព
         10 វិនាទីបន្ទាប់ពីការចុចគ្រាប់ចុចចុងក្រោយ → ផ្ញើ {type:"t", state:"stop"}
អ្នកទទួល៖ បញ្ឈប់ដោយស្វ័យប្រវត្តិ 10 វិនាទីបន្ទាប់ពី "ចាប់ផ្តើម" ចុងក្រោយប្រសិនបើគ្មាន "បញ្ឈប់" មកដល់

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS ផ្សាយ {type:"c", kind:"invite", call_id}
WS ការផ្សាយ {ប្រភេទ៖"គ", ប្រភេទ៖"ផ្តល់ជូន", sdp}
WS ផ្សាយ {ប្រភេទ៖"គ", ប្រភេទ៖"ចម្លើយ", sdp}
WS ផ្សាយ {ប្រភេទ៖ "គ", ប្រភេទ៖"បេក្ខជន", ទឹកកក} × អិន
POST /api/calls/{call_id}/end

federation.h2_f:
ស្រោមសំបុត្រ = {
  ប្រភព_node៖ hex32,
  target_user៖ int64,
  inner_ciphertext: បៃ,
  inner_nonce : បៃ,
  send_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(ស្រោមសំបុត្រ))
POST /federation/deliver { envelope, sig }

gossip.h3_f:
advertisement = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(ការផ្សាយពាណិជ្ជកម្ម))
gossip payload: [..., { ad, sig}, ...]

អ្នកទទួល៖ ផ្ទៀងផ្ទាត់ sig ប្រឆាំងនឹង ad.pubkey → store iff ok
បន្ថែម៖ PoW នៃ 2^18 លេខសូន្យនាំមុខនៅលើ {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template ជាមួយ {
  ចៃដន្យ = ចៃដន្យរបស់យើង,
  server_name = ឈ្មោះម៉ាស៊ីនរបស់យើង (ឬ ECH-រុំ),
  session_id = លេខសម្គាល់សម័យរបស់យើង,
}
JA4 = t13d_xxxx_xxxx_xxxx (ត្រូវគ្នានឹង Chrome មានស្ថេរភាព)

stealth.h4_f:
DoH៖ POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH៖ ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA៖ domain(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE៖ didReceive(request) { decrypt(request.content.userInfo) }
Android FCM៖ onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
គេហទំព័រ SW៖ self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
tool = sign_tool
បញ្ចូល = មែកធាងប្រភព, keys/release.key
manifest = {
  កំណែ៖ "0.1.0",
  built_at៖ unix_ms,
  ឯកសារ៖ [{ផ្លូវ, sha256, ទំហំ}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
លទ្ធផល = INTEGRITY.sig.json = { manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
បង្កើត៖ POST /api/bots { username, display_name, code}
          → {bot_id, token, pubkey}
ដំណើរការ៖ នៅក្នុងដំណើរការ (coroutine នៅខាងក្នុងថ្នាំង)
      OR ខាងក្រៅ (ការស្ទង់មតិវែង /api/bots/{id}/updates, token-auth'd)
សារ៖ {អត្ថបទ ហត្ថលេខា៖ Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
នៅ​លើ /start {
  បញ្ចេញ "សូមស្វាគមន៍ {ctx.first_name}"
}
នៅលើ /add <item> {
  state.list = (state.list ឬ []) + [ctx.args.item]
  បញ្ចេញ "បន្ថែម៖ {ctx.args.item}"
}

security.h4_f:
canary.txt (ប្រចាំថ្ងៃ)៖
  {date, sig: Ed25519-Sign(release_priv, date)}
អតិថិជនផ្ទៀងផ្ទាត់ → អវត្តមាន ឬមិនត្រឹមត្រូវ ⇒ ការសម្របសម្រួលដែលសង្ស័យ

គ្រាអាសន្ន៖
  admin POST /api/admin/revoke-all {ហេតុផល}
  node broadcasts {type:"n", event:"compromise", reason}
  អតិថិជនលុបសោ បង្ខំឱ្យចាប់ផ្ដើមឡើងវិញ

debugging.h2_f:
អត្រាអ៊ីស្តូក្រាម (ក្នុងមួយផ្លូវ + វិធីសាស្ត្រ)៖
  vortex_http_requests_total{route,method,status}
  vortex_http_request_duration_seconds_bucket{route,method,le}

រង្វាស់រន្ធបណ្តាញ៖
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{room,user}

បញ្ជរផ្ទាល់ខ្លួន៖
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

