fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  មាតិកា, -- ជួរឈរនិមិត្តសញ្ញា
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
សំណួរ៖ SELECT rowid FROM messages_fts WHERE មាតិកា MATCH 'foo'

